"""Transitive Closure — Warshall's algorithm (Floyd-Warshall with OR).

Time: O(n^3)   Space: O(n^2)
"""
from typing import List


class Solution:
    def transitiveClosure(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        reach = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        for u, v in edges:
            reach[u][v] = 1
        for k in range(n):
            for i in range(n):
                if reach[i][k]:
                    for j in range(n):
                        if reach[k][j]:
                            reach[i][j] = 1
        return reach
